const AMB = { t: 3, water: null, crowd: null, wg: null, cg: null };
function ambLoop(filterType, freq, q) { const c = actx(); const b = c.createBuffer(1, c.sampleRate * 2, c.sampleRate); const d = b.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1; const src = c.createBufferSource(); src.buffer = b; src.loop = true; const f = c.createBiquadFilter(); f.type = filterType; f.frequency.value = freq; f.Q.value = q || 0.7; const g = c.createGain(); g.gain.value = 0; src.connect(f).connect(g).connect(c.destination); src.start(); return g; }
function birdChirp() { const base = 1800 + Math.random() * 1400; const n = 2 + Math.floor(Math.random() * 3); for (let i = 0; i < n; i++) setTimeout(() => tone(base + Math.random() * 400, 0.09, "sine", 0.018, base + 900 + Math.random() * 600), i * (110 + Math.random() * 90)); }
function updateAudio(dt) { if (!audioReady) return; const on = soundOn ? 1 : 0, jet = riding && riding.kind === "jet" ? Math.min(1, vSpeed / 60) : 0; const golfNear = player && Math.hypot(player.position.x - GOLF.origin[0], player.position.z - GOLF.origin[1]) < 420 ? 1 : 0; const target = { wind: 0.25 + 0.75 * (1 - night) + jet * 1.2 + golfNear * 0.45 * (1 - night), night: night * (1 - jet) };
  if (player && on) { if (!AMB.wg) { AMB.wg = ambLoop("lowpass", 520, 0.5); AMB.cg = ambLoop("bandpass", 420, 0.6); AMB.ph = 0; } AMB.ph += dt; const dl = Math.hypot(player.position.x - LAKE.x, player.position.z - LAKE.z) - (LAKE.r || 0); let dp = 1e9; for (const pd of PONDS) dp = Math.min(dp, Math.hypot(player.position.x - pd.x, player.position.z - pd.z) - pd.r); const wk = inside ? 0 : Math.max(0, 1 - Math.max(0, Math.min(dl, dp + 20)) / 70); AMB.wg.gain.value += ((0.12 + 0.06 * Math.sin(AMB.ph * 2.4) + 0.04 * Math.sin(AMB.ph * 0.7)) * wk * VOL.amb * VOL.master - AMB.wg.gain.value) * Math.min(1, dt * 2);
    let dt2 = 1e9; for (const h of HUBS) if (["Main Street", "The Landing", "Design District"].includes(h[0])) dt2 = Math.min(dt2, Math.hypot(player.position.x - h[1], player.position.z - h[2])); const ck = inside ? 0 : Math.max(0, 1 - dt2 / 90) * (0.5 + 0.5 * (1 - night)); AMB.cg.gain.value += (0.035 * ck * VOL.amb * VOL.master - AMB.cg.gain.value) * Math.min(1, dt * 2);
    if (!AMB.fg) AMB.fg = ambLoop("bandpass", 1400, 0.5); let df = 1e9; if (TERM.fountains) for (const f of TERM.fountains) df = Math.min(df, Math.hypot(player.position.x - f.g.position.x, player.position.z - f.g.position.z)); const fk = inside ? 0 : Math.max(0, 1 - Math.max(0, df - 4) / 20); AMB.fg.gain.value += (0.11 * fk * VOL.amb * VOL.master - AMB.fg.gain.value) * Math.min(1, dt * 2);
    AMB.t -= dt; if (AMB.t <= 0) { AMB.t = 2.5 + Math.random() * 6; let dc = 1e9; const cm = HUBS.find((h) => h[0] === "The Commons"); if (cm) dc = Math.hypot(player.position.x - cm[1], player.position.z - cm[2]); if (!inside && night < 0.6 && Math.min(dl, dp, dc - 60) < 110) birdChirp(); } }
  else if (AMB.wg) { AMB.wg.gain.value = 0; AMB.cg.gain.value = 0; if (AMB.fg) AMB.fg.gain.value = 0; } { const inCar = cartMode || (riding && riding.kind === "cart"); RADIO.fade = Math.min(1, RADIO.fade + dt * 0.5); const want = RADIO.i < 0 ? 0 : on * RADIO.fade * (inCar ? 0.5 : inside ? 0.12 : 0.26) * (jet ? 0.3 : 1); RADIO.a.volume += (want * VOL.music * VOL.master - RADIO.a.volume) * Math.min(1, dt * 2); } for (const k in target) { const a = AUD[k], want = Math.min(1, on * +a.dataset.vol * target[k]) * VOL.amb * VOL.master; a.volume += (want - a.volume) * Math.min(1, dt * 1.5); } }
addEventListener("pointerdown", (e) => { if (BUILD.on && e.button === 0 && !e.target.closest(".card, .hud")) placeBuild(); }); addEventListener("pointerdown", startAudio); addEventListener("keydown", startAudio); $("#snd").addEventListener("click", (e) => { e.stopPropagation(); toggleSound(); });

// ───────────────────────────── synthesised sound effects ─────────────────────────────
let ACTX = null, engine = null, engineGain = null, stepTimer = 0;
function actx() { if (!ACTX) { ACTX = new (window.AudioContext || window.webkitAudioContext)(); } if (ACTX.state === "suspended") ACTX.resume(); return ACTX; }
function tone(f, dur, type, vol, slide) { if (!soundOn) return; const c = actx(); const o = c.createOscillator(), g = c.createGain(); o.type = type || "sine"; o.frequency.value = f; if (slide) o.frequency.exponentialRampToValueAtTime(slide, c.currentTime + dur); g.gain.value = Math.max(0.0001, (vol || 0.08) * VOL.sfx * VOL.master); g.gain.exponentialRampToValueAtTime(0.0001, c.currentTime + dur); o.connect(g).connect(c.destination); o.start(); o.stop(c.currentTime + dur); }
function noise(dur, vol, hp) { if (!soundOn) return; const c = actx(); const b = c.createBuffer(1, c.sampleRate * dur, c.sampleRate); const d = b.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / d.length); const src = c.createBufferSource(); src.buffer = b; const f = c.createBiquadFilter(); f.type = "highpass"; f.frequency.value = hp || 800; const g = c.createGain(); g.gain.value = Math.max(0.0001, (vol || 0.05) * VOL.sfx * VOL.master); src.connect(f).connect(g).connect(c.destination); src.start(); }
function sfx(name) {
  if (name === "step") noise(0.07, 0.035, 600); else if (name === "jump") tone(240, 0.18, "triangle", 0.05, 480); else if (name === "land") noise(0.09, 0.05, 300);
  else if (name === "coin") { tone(880, 0.12, "sine", 0.06); setTimeout(() => tone(1320, 0.18, "sine", 0.06), 90); } else if (name === "buy") { tone(660, 0.1, "square", 0.04); setTimeout(() => tone(990, 0.16, "square", 0.04), 100); }
  else if (name === "ui") tone(520, 0.06, "sine", 0.04); else if (name === "putt") noise(0.05, 0.08, 1500); else if (name === "rank") { [523, 659, 784, 1046].forEach((f, i) => setTimeout(() => tone(f, 0.25, "triangle", 0.06), i * 110)); }
  else if (name === "board") tone(300, 0.2, "sawtooth", 0.03, 120); else if (name === "rattle") { for (let i = 0; i < 14; i++) setTimeout(() => noise(0.03, 0.06, 3000), i * 45); } else if (name === "swing") { noise(0.12, 0.07, 400); setTimeout(() => tone(180, 0.05, "square", 0.05), 60); } else if (name === "gate") tone(1200, 0.08, "sine", 0.05);
}
function updateSfx(dt) {
  if (!audioReady || !soundOn) { if (engineGain) engineGain.gain.value = 0; return; }
  const c = actx();
  if (!engine) { engine = c.createOscillator(); engine.type = "sawtooth"; const lp = c.createBiquadFilter(); lp.type = "lowpass"; lp.frequency.value = 600; engineGain = c.createGain(); engineGain.gain.value = 0; engine.connect(lp).connect(engineGain).connect(c.destination); engine.start(); }
  const drivingCart = cartMode || (riding && riding.kind === "cart"); const flying = riding && riding.kind === "jet";
  const sp = drivingCart ? Math.abs(riding ? vSpeed : cartSpeed) : (flying ? vSpeed : 0);
  const want = drivingCart ? Math.min(0.06, 0.012 + sp * 0.0015) : (flying ? Math.min(0.09, 0.02 + sp * 0.0006) : 0);
  engineGain.gain.value += (want - engineGain.gain.value) * Math.min(1, dt * 4); engine.frequency.value = drivingCart ? 55 + sp * 4 : (flying ? 40 + sp * 0.5 : 50);
  if (!riding && !cartMode && !airborne && !golf.playing) { const moving = keys.KeyW || keys.KeyS || keys.KeyA || keys.KeyD || joy.active; if (moving) { stepTimer -= dt; if (stepTimer <= 0) { sfx("step"); stepTimer = (keys.ShiftLeft || keys.ShiftRight) ? 0.28 : 0.45; } } }
}

